package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Material role/focus checks and real compact pages. No playback or external data. */
public final class MaterialShellTests extends Instrumentation {
 int checks;boolean activate,activated;Activity page;
 public void onCreate(Bundle b){activate=b!=null&&"true".equals(b.getString("activate"));start();}
 void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 static double contrast(int a,int b){double x=Color.luminance(a),y=Color.luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 Object field(Object o,String name)throws Exception{for(Class<?> type=o.getClass();type!=null;type=type.getSuperclass())try{Field f=type.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
 void ui(final Runnable task){final Throwable[] error={null};runOnMainSync(new Runnable(){public void run(){try{task.run();}catch(Throwable t){error[0]=t;}}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 void close(){if(page!=null){final Activity a=page;ui(new Runnable(){public void run(){a.finish();}});page=null;}}
 public void onStart(){final Context base=getTargetContext();final String token="material-check-"+UUID.randomUUID();final File dir=new File(base.getCacheDir(),token);dir.mkdir();Context fixture=new ContextWrapper(base){public File getFilesDir(){return dir;}public SharedPreferences getSharedPreferences(String name,int mode){return base.getSharedPreferences(token+name,mode);}};Map<String,?> home=new HashMap<String,Object>(base.getSharedPreferences("home-canvas",0).getAll());String order=base.getSharedPreferences("appearance",0).getString("app-order","");Bundle out=new Bundle();try{
 check(Appearance.THEMES.length==Appearance.COLORS.length&&ThemePacks.NAMES.length==ThemePacks.THEMES.length,"complete style registry");fixture.getSharedPreferences("appearance",0).edit().putInt("theme",16).putBoolean("list",true).commit();StockWallpapers.apply(fixture,1);byte[] before=BackupEngine.bytes(Appearance.wallpaper(fixture),2097152);ThemeCheckpoint.apply(fixture,6,true);Appearance.Palette p=Appearance.palette(fixture);
 check(p.material()&&!p.classic()&&!p.sxmo(),"Material roles selected");check(contrast(p.ink,p.selection)>=4.5,"selected text contrast");check(contrast(Color.WHITE,p.background)>=4.5,"body text contrast");check(contrast(p.accent,p.selection)>=3,"visible keypad focus outline");check(!fixture.getSharedPreferences("appearance",0).getBoolean("list",true),"compact grid retained");
 Bitmap wallpaper=BitmapFactory.decodeFile(Appearance.wallpaper(fixture).getPath());check(wallpaper!=null&&wallpaper.getWidth()==240&&wallpaper.getHeight()==302,"Material wallpaper decodes");wallpaper.recycle();Bitmap sample=Bitmap.createBitmap(100,40,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(sample);Drawable row=UiChrome.row(p,8,1);row.setBounds(0,0,100,40);row.setState(new int[]{android.R.attr.state_selected});row.draw(canvas);check(sample.getPixel(50,20)==p.selection,"selected row container");row.setState(new int[]{});row.draw(canvas);check(sample.getPixel(50,20)==p.background,"unselected row surface");Drawable bar=UiChrome.panel(p,1,false);bar.setBounds(0,0,100,40);bar.draw(canvas);check(sample.getPixel(50,20)==p.background,"clean Material header surface");sample.recycle();
 ThemeCheckpoint.restore(fixture);check(fixture.getSharedPreferences("appearance",0).getInt("theme",-1)==16&&fixture.getSharedPreferences("appearance",0).getBoolean("list",false),"previous classic settings restored");check(Arrays.equals(before,BackupEngine.bytes(Appearance.wallpaper(fixture),2097152)),"previous wallpaper restored exactly");
 if(activate){ThemeCheckpoint.apply(base,6,true);activated=true;}
 check(AppCatalog.menuOrder(base,0).length==9,"nine primary apps retained");check(home.equals(base.getSharedPreferences("home-canvas",0).getAll())&&order.equals(base.getSharedPreferences("appearance",0).getString("app-order","")),"custom Home and app order preserved");
 page=startActivitySync(new Intent(base,PersonalizationActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();final Activity actual=page;ui(new Runnable(){public void run(){try{check(((List<?>)field(actual,"listRows")).size()==5,"compact personalization retained");if(activate)check(((Appearance.Palette)field(actual,"palette")).material(),"Material applied to native Leo page");}catch(Exception e){throw new RuntimeException(e);}}});close();check(Class.forName("com.android.vcard.VCardComposer")!=null,"external dependency loading retained");out.putString("result","PASS "+checks+" Material style and preservation checks");out.putBoolean("activated",activate);
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));if(activated)try{ThemeCheckpoint.restore(base);}catch(Exception restore){out.putString("restore_error",restore.toString());}}
 finally{close();for(String name:new String[]{"appearance","accessibility"})base.getSharedPreferences(token+name,0).edit().clear().commit();File[] files=dir.listFiles();if(files!=null)for(File f:files)f.delete();dir.delete();}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
